cases = json.load(open('cases.json'))['cases']
enumerators = {'resume_skips_ticked_checklist','tools_status_lists_all','section_header_not_empty'}
for c in cases:
  if c.get('id') in enumerators: continue
  blob = json.dumps(c).lower()
  for kw in ['predict','tamtamy','desk booking','sharepoint','gitlab','collaboration','events','bench','hr contact','servus','tool access','microsoft teams']:
    if kw in blob:
      print(f'{c[\"id\"]:40s}  <- {kw}')
